		return debruijn64[(y&-y)*0x022fdd63cc95386dull >> 58];
	} else {
		static const char debruijn32[32] = {
			0, 1, 23, 2, 29, 24, 19, 3, 30, 27, 25, 11, 20, 8, 4, 13,
			31, 22, 28, 18, 26, 10, 7, 12, 21, 17, 9, 6, 16, 5, 15, 14
		};
