#include <errno.h>

time_t mktime(struct tm *tm)
{
	struct tm new;
	long long t = __tm_to_secs(tm);

	if (__secs_to_tm(t, &new) < 0) goto error;
	new.tm_isdst = 0;

	*tm = new;
	return t;

